import json
from pathlib import Path

root = Path.cwd()
evidence = root / "work/ceres-v3/05/evidence/controlled-20261005T213814Z-e9eee78c"
run = evidence / "core-002"
old = json.loads((evidence / "core-001/case-node-map.json").read_text(encoding="utf-8"))
trace = [
    json.loads(line)
    for line in (run / "phase-002-core16-goal-protocol/trace.jsonl").read_text(encoding="utf-8").splitlines()
]
results = {
    record["nodeid"]: record["outcome"]
    for record in trace
    if record.get("kind") == "test_result"
}
rows = []
for case in old["case_results"]:
    nodes = case["actual_collected_execution_nodes"]
    outcomes = [results.get(node, "not-reported") for node in nodes]
    rows.append({
        "case_id": case["case_id"],
        "actual_nodes": nodes,
        "node_outcomes": outcomes,
        "result": "pass" if outcomes and all(value == "passed" for value in outcomes) else "fail-or-incomplete",
    })
phase1 = [
    json.loads(line)
    for line in (run / "phase-001-r01-r08/trace.jsonl").read_text(encoding="utf-8").splitlines()
]
plans = {}
for record in phase1:
    if record.get("kind") != "sse_events":
        continue
    for event in record["events"]:
        payload = event.get("payload", {})
        items = (payload.get("plan") or {}).get("items") or []
        if event.get("type") == "turn.completed" and items:
            plans[record["nodeid"]] = [
                {"sku_id": item.get("sku_id"), "quantity": item.get("quantity")}
                for item in items
            ]

data = {
    "case_version": old["case_version"],
    "phase_001_gate": {
        "R01": {"outcome": "passed", "actual_completed_plan": plans.get(old["case_results"][0]["actual_collected_execution_nodes"][0])},
        "R08": {"outcome": "passed", "actual_completed_plan": plans.get(old["case_results"][7]["actual_collected_execution_nodes"][0])},
    },
    "phase_002_original_18_case_mapping": rows,
    "phase_002_goal_protocol_regressions": [
        "tests/test_goal_understanding.py::test_explicit_product_purchase_is_ready",
        "tests/test_goal_decision_gate.py::test_a_product_purchase_never_asks_about_people",
    ],
    "phase_002_all_18_fixed_cases_pass": all(row["result"] == "pass" for row in rows),
}
(run / "case-results.json").write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
